using System.Data;using System.Text;using Dapper;using Microsoft.Data.SqlClient;using Microsoft.Extensions.Configuration;using GraphApi.Models.SGR.MenusBotones;namespace GraphApi.Services.SGR.MenusBotones{    public class MenusBotonesService : IMenusBotonesService    {        private readonly IDbConnection   _objDbDefault;        private readonly IConfiguration  _objConfig;        public MenusBotonesService(IDbConnection objDbDefault, IConfiguration objConfig)        {            _objDbDefault = objDbDefault;            _objConfig    = objConfig;        }        public async Task<IEnumerable<clReadMenusBotones>> GetMenusBotones(            int userId,            string windowName)        {            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT  *                 FROM sgr.vsMenusBotones (NOLOCK)            ");            var vParameters = new DynamicParameters();            var vList = await _objDbDefault.QueryAsync<clReadMenusBotones>(vSql.ToString(), vParameters);            return vList;        }        public async Task<IEnumerable<dynamic>> GetMenusBotonesDynamic(            int? menuBotonID,            int? menuID,            string? tituloMenu,            string? boton,            string? accion,            int? orden,            bool? bEliminado,            string? columnNames,            int userId,            string windowName)        {            string sColumnNames = string.IsNullOrWhiteSpace(columnNames) ? "MenuBotonID, MenuID, TituloMenu, Boton, Accion, Orden, bEliminado" : columnNames;            var vSql = new StringBuilder($@"                --WindowName:{windowName},UserID:{userId}                SELECT {sColumnNames}                FROM sgr.vsMenusBotones (NOLOCK)                WHERE 1=1            ");            var vParameters = new DynamicParameters();            if (menuBotonID.HasValue)            {                vSql.Append(" AND MenuBotonID = @MenuBotonID");                vParameters.Add("MenuBotonID",menuBotonID);            }            if (!string.IsNullOrWhiteSpace(tituloMenu))            {                vSql.Append(" AND TituloMenu LIKE @TituloMenu");                vParameters.Add("TituloMenu",$"%{tituloMenu}%");            }            if (!string.IsNullOrWhiteSpace(boton))            {                vSql.Append(" AND Boton LIKE @Boton");                vParameters.Add("Boton",$"%{boton}%");            }            if (!string.IsNullOrWhiteSpace(accion))            {                vSql.Append(" AND Accion LIKE @Accion");                vParameters.Add("Accion",$"%{accion}%");            }            if (bEliminado.HasValue)            {                vSql.Append(" AND bEliminado = @bEliminado");                vParameters.Add("bEliminado", bEliminado.Value);            }            var vList = await _objDbDefault.QueryAsync<dynamic>(vSql.ToString(), vParameters);            return vList;        }        public async Task<clReadMenusBotones> CreateMenusBotones(clCreateMenusBotones objInput, int userId, string windowName)        {            string sInsertSql = $@"                --WindowName:{windowName},UserID:{userId}                INSERT INTO sgr.MenusBotones                (MenuID, Boton, Accion, Icono, Orden, bEliminado, Creado, UsuarioCreacionID, FechaCreacion)                VALUES (@MenuID, @Boton, @Accion, @Icono, @Orden, @bEliminado, @Creado, @UsuarioCreacionID, GETDATE());                SELECT CAST(SCOPE_IDENTITY() AS INT);            ";            var vInsertParams = new            {                objInput.MenuID,                objInput.Boton,                objInput.Accion,                objInput.Icono,                objInput.Orden,                objInput.bEliminado,                Creado     = windowName,                UsuarioCreacionID = userId            };            var vNewId = await _objDbDefault.ExecuteScalarAsync<int>(sInsertSql, vInsertParams);            string sSelectSql = @"                SELECT MenuBotonID, MenuID, TituloMenu, Boton, Accion, Orden, bEliminado                FROM sgr.vsMenusBotones (NOLOCK)                WHERE MenuBotonID = @MenuBotonID;";            var vReadParams = new { MenuBotonID = vNewId };            var vCreated = await _objDbDefault.QuerySingleOrDefaultAsync<clReadMenusBotones>(sSelectSql, vReadParams);            if (vCreated is null) throw new InvalidOperationException($"No se pudo recuperar el MenusBotone con ID {vNewId}.");            return vCreated;        }        public async Task<clReadMenusBotones?> UpdateMenusBotones(clUpdateMenusBotones objInput, int userId, string windowName)        {            var vSets = new List<string>();            var vParameters = new DynamicParameters();            vParameters.Add("MenuBotonID", objInput.MenuBotonID);            if (objInput.MenuID != null)            {                vSets.Add("MenuID = @MenuID");                vParameters.Add("MenuID", objInput.MenuID);            }            if (objInput.Boton is not null)            {                vSets.Add("Boton = @Boton");                vParameters.Add("Boton", objInput.Boton);            }            if (objInput.Accion is not null)            {                vSets.Add("Accion = @Accion");                vParameters.Add("Accion", objInput.Accion);            }            if (objInput.Icono is not null)            {                vSets.Add("Icono = @Icono");                vParameters.Add("Icono", objInput.Icono);            }            if (objInput.Orden != null)            {                vSets.Add("Orden = @Orden");                vParameters.Add("Orden", objInput.Orden);            }            if (objInput.bEliminado != null)            {                vSets.Add("bEliminado = @bEliminado");                vParameters.Add("bEliminado", objInput.bEliminado);            }            vSets.Add($"Modificado = '{windowName}'");            vSets.Add($"UsuarioModificacionID = {userId}");            vSets.Add("FechaModificacion = GETDATE()");            var vSetClause = string.Join(", ", vSets);            var sSql = $@"                --WindowName:{windowName},UserID:{userId}                UPDATE sgr.MenusBotones                SET {vSetClause}                WHERE MenuBotonID = @MenuBotonID;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, vParameters);            if (vAffected == 0) return null;            const string sSelect = @"                SELECT MenuBotonID, MenuID, TituloMenu, Boton, Accion, Orden, bEliminado                FROM sgr.vsMenusBotones (NOLOCK)                WHERE MenuBotonID = @MenuBotonID;";            return await _objDbDefault.QueryFirstOrDefaultAsync<clReadMenusBotones>(sSelect, new {  objInput.MenuBotonID });        }        public async Task<bool> DeleteMenusBotones(int nMenusBotonesID)        {            const string sSql = @"                DELETE FROM sgr.MenusBotones                WHERE MenuBotonID = @Id;";            var vAffected = await _objDbDefault.ExecuteAsync(sSql, new { Id = nMenusBotonesID });            return vAffected > 0;        }    }}